import { useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, Check, CheckCircle2, Clock3, Copy, Database, Download, FileSpreadsheet, FolderOpen, FolderPlus, History, ImagePlus, LayoutGrid, ListChecks, Loader2, MessageCircle, Palette, RotateCcw, ShieldCheck, Sparkles, Trash2, Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import type { MarketplaceBrandPreset } from "@/components/BrandPresetManagerDialog";
import { MARKETPLACE_CHANNELS, MARKETPLACE_FONT_STYLES, MARKETPLACE_LIFESTYLE_STYLES, getMarketplaceSuite, getMarketplaceSuiteCreditCost, type MarketplaceBrandStyle, type MarketplaceChannel, type MarketplaceImageRole, type MarketplaceLifestyleStyle } from "@shared/marketplaceSuites";
import { getMarketplaceDetailSpecificationLines, MARKETPLACE_DETAIL_SPECIFICATION_LAYOUTS, type MarketplaceDetailSpecificationLayout, type MarketplaceLifestyleRecommendation, type MarketplaceLifestyleSceneCandidate, type MarketplaceProductBrief } from "@shared/marketplaceProductBrief";
import type { MarketplaceListingCopy } from "@shared/marketplaceListingCopy";
import { compareMarketplaceProductBriefs, type MarketplaceProductBriefSnapshot } from "@/lib/marketplaceDraftHistory";
import { appendMarketplaceRevisionInstruction, MARKETPLACE_DRAFT_REVISION_SHORTCUTS } from "@/lib/marketplaceDraftRevision";
import type { MarketplaceReferenceImage, MarketplaceSuiteResult } from "@/lib/marketplaceSuite";
import { formatMarketplaceGenerationSeconds, type MarketplaceGenerationProgress } from "@/lib/marketplaceGenerationProgress";
import type { SavedMarketplaceProduct } from "@/lib/marketplaceProductLibrary";
import { getProjectOptionLabel, type PhotoProject, type PhotoProjectCreateInput } from "@/lib/photoProjects";
import { getMarketplaceProjectQuickCreateState } from "@/lib/marketplaceProjectQuickCreate";
import { getMarketplaceLifestyleRecommendationStatus } from "@/lib/marketplaceLifestyleRecommendation";
import { getMarketplaceWorkspaceStage, getMarketplaceWorkspaceStepState } from "@/lib/marketplaceWorkspace";
import { formatMarketplaceDimensions, parseMarketplaceDimensions } from "@/lib/marketplaceDimensions";
import { getThailandMarketplaceListingCharacterStatus, getThailandMarketplaceListingRequirements, normaliseThailandMarketplaceListingFields, type ThailandMarketplaceListingFields } from "@shared/thailandMarketplaceListing";
import type { MarketplaceWorkflow } from "@shared/marketplaceWorkflows";

type MarketplaceSuiteDialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  channel: MarketplaceChannel;
  productBrief: MarketplaceProductBrief;
  referenceImages: MarketplaceReferenceImage[];
  selectedRoles: MarketplaceImageRole[];
  detailSpecificationLayout: MarketplaceDetailSpecificationLayout;
  lifestyleStyle: MarketplaceLifestyleStyle;
  lifestyleRecommendation: MarketplaceLifestyleRecommendation | null;
  selectedLifestyleScene: MarketplaceLifestyleSceneCandidate | null;
  lifestyleAvoidStyles: Array<"home" | "office" | "outdoor">;
  lifestyleStyleIsMerchantSelected: boolean;
  brandStyle: MarketplaceBrandStyle;
  isAuthenticated: boolean;
  brandPresets: MarketplaceBrandPreset[];
  activeBrandPresetId: number | null;
  workflows: MarketplaceWorkflow[];
  isSavingWorkflow: boolean;
  projects: PhotoProject[];
  selectedProjectId: number | null;
  sku: string;
  savedProducts: SavedMarketplaceProduct[];
  isSavingProduct: boolean;
  isCreatingProject: boolean;
  isDrafting: boolean;
  draftProgress: number;
  draftElapsed: string;
  draftFailure: string | null;
  draftRevisionInstruction: string;
  draftHistory: MarketplaceProductBriefSnapshot[];
  listingCopy: MarketplaceListingCopy | null;
  isListingCopyDrafting: boolean;
  isGenerating: boolean;
  generationProgress: MarketplaceGenerationProgress | null;
  retryingRole: MarketplaceImageRole | null;
  result: MarketplaceSuiteResult | null;
  onChannelChange: (channel: MarketplaceChannel) => void;
  onProductBriefChange: (brief: MarketplaceProductBrief) => void;
  onReferencesSelected: (files: File[]) => void;
  onRemoveReference: (index: number) => void;
  onSelectedRolesChange: (roles: MarketplaceImageRole[]) => void;
  onDetailSpecificationLayoutChange: (layout: MarketplaceDetailSpecificationLayout) => void;
  onLifestyleStyleChange: (style: MarketplaceLifestyleStyle) => void;
  onApplyLifestyleRecommendation: () => void;
  onSelectLifestyleScene: (candidate: MarketplaceLifestyleSceneCandidate) => void;
  onToggleLifestyleAvoidStyle: (style: "home" | "office" | "outdoor") => void;
  onBrandStyleChange: (style: MarketplaceBrandStyle) => void;
  onBrandPresetChange: (presetId: number | null) => void;
  onSaveWorkflow: (name: string) => Promise<boolean>;
  onApplyWorkflow: (workflow: MarketplaceWorkflow) => void;
  onRemoveWorkflow: (workflow: MarketplaceWorkflow) => void;
  onProjectChange: (projectId: number | null) => void;
  onCreateProject: (input: PhotoProjectCreateInput) => Promise<void>;
  onSkuChange: (sku: string) => void;
  onSaveProduct: () => void;
  onLoadSavedProduct: (product: SavedMarketplaceProduct) => void;
  onManageBrandPresets: () => void;
  onDraft: () => void;
  onDraftRevisionInstructionChange: (instruction: string) => void;
  onRestoreDraft: (snapshot: MarketplaceProductBriefSnapshot) => void;
  onClearDraftHistory: () => void;
  onRenameDraft: (snapshotId: string, name: string) => void;
  onDraftListingCopy: () => void;
  onListingCopyChange: (copy: MarketplaceListingCopy) => void;
  onCopyListingText: (kind: "title" | "bullets") => void;
  onExportProductData: (format: "csv" | "xlsx") => void;
  onExportPlatformTemplate: (format: "csv" | "xlsx") => void;
  onGenerate: () => void;
  onRetryRole: (role: MarketplaceImageRole) => void;
  onRedesignRole: (role: MarketplaceImageRole, instruction: string) => void;
  onDownload: (url: string, role: MarketplaceImageRole) => void;
  onShare: (url: string, role: MarketplaceImageRole) => void;
  onShareAll: () => void;
  sharingRole: MarketplaceImageRole | "all" | null;
  onDownloadAll: () => void;
  onOpenLibrary: () => void;
};

function linesToText(lines: string[]) { return lines.join("\n"); }
function textToLines(value: string) { return value.split("\n").map((line) => line.trim()).filter(Boolean).slice(0, 6); }
function formatDraftTime(createdAt: number) { return new Date(createdAt).toLocaleTimeString("zh-HK", { hour: "2-digit", minute: "2-digit" }); }

function BriefLinesEditor({ id, label, value, placeholder, onChange }: { id: string; label: string; value: string[]; placeholder: string; onChange: (lines: string[]) => void }) {
  return <div>
    <label htmlFor={id} className="text-[10px] font-bold tracking-[0.1em] text-[#3974bf]">{label}</label>
    <textarea id={id} value={linesToText(value)} onChange={(event) => onChange(textToLines(event.target.value))} placeholder={placeholder} className="mt-1.5 min-h-16 w-full resize-y rounded-xl border border-[#d3e0ee] bg-[#fbfdff] p-2.5 text-xs leading-5 text-[#314963] outline-none focus:border-[#6ba1e2] focus:ring-2 focus:ring-[#e4f0ff]" />
    <p className="mt-1 text-[10px] text-[#7c8ca0]">每行一項，最多 6 項。</p>
  </div>;
}

function SpecificationProofreadReminder({ outputKey, lines, acknowledged, onAcknowledgedChange }: { outputKey: string; lines: string[]; acknowledged: boolean; onAcknowledgedChange: (outputKey: string, next: boolean) => void }) {
  return <div role="alert" className="mt-2 rounded-lg border border-[#f0d4a7] bg-[#fffaf1] p-2 text-[10px] leading-4 text-[#765426]">
    <div className="flex items-start gap-1.5"><ShieldCheck size={13} className="mt-0.5 shrink-0 text-[#bd7a0f]" /><div><strong className="block">規格文字校對</strong><p className="mt-0.5">AI 圖內文字可能有排字或單位錯誤。上架前請與以下已確認資料逐字比較：</p></div></div>
    <div className="mt-1.5 flex flex-wrap gap-1">{lines.map((line) => <span key={line} className="rounded-md border border-[#e5c78e] bg-white px-1.5 py-0.5 font-bold text-[#6f4c1b]">{line}</span>)}</div>
    <label className="mt-2 flex cursor-pointer items-start gap-1.5 text-[#6b552d]"><input type="checkbox" checked={acknowledged} onChange={(event) => onAcknowledgedChange(outputKey, event.target.checked)} className="mt-0.5 h-3.5 w-3.5 rounded border-[#c79a4e] text-[#176bd2] focus:ring-[#e5c78e]" /><span>已核對數值、單位、長 × 闊 × 高次序及中文文字；不一致便應重新設計，勿直接上架。</span></label>
  </div>;
}

export function MarketplaceSuiteDialog({ open, onOpenChange, channel, productBrief, referenceImages, selectedRoles, detailSpecificationLayout, lifestyleStyle, lifestyleRecommendation, selectedLifestyleScene, lifestyleAvoidStyles, lifestyleStyleIsMerchantSelected, brandStyle, isAuthenticated, brandPresets, activeBrandPresetId, workflows, isSavingWorkflow, projects, selectedProjectId, sku, savedProducts, isSavingProduct, isCreatingProject, isDrafting, draftProgress, draftElapsed, draftFailure, draftRevisionInstruction, draftHistory, listingCopy, isListingCopyDrafting, isGenerating, generationProgress, retryingRole, result, onChannelChange, onProductBriefChange, onReferencesSelected, onRemoveReference, onSelectedRolesChange, onDetailSpecificationLayoutChange, onLifestyleStyleChange, onApplyLifestyleRecommendation, onSelectLifestyleScene, onToggleLifestyleAvoidStyle, onBrandStyleChange, onBrandPresetChange, onSaveWorkflow, onApplyWorkflow, onRemoveWorkflow, onProjectChange, onCreateProject, onSkuChange, onSaveProduct, onLoadSavedProduct, onManageBrandPresets, onDraft, onDraftRevisionInstructionChange, onRestoreDraft, onClearDraftHistory, onRenameDraft, onDraftListingCopy, onListingCopyChange, onCopyListingText, onExportProductData, onExportPlatformTemplate, onGenerate, onRetryRole, onRedesignRole, onDownload, onShare, onShareAll, sharingRole, onDownloadAll, onOpenLibrary }: MarketplaceSuiteDialogProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const revisionInputRef = useRef<HTMLTextAreaElement>(null);
  const resultSectionRef = useRef<HTMLElement>(null);
  const previousResultRef = useRef<MarketplaceSuiteResult | null>(null);
  const [compareSnapshotId, setCompareSnapshotId] = useState<string | null>(null);
  const [newProjectName, setNewProjectName] = useState("");
  const [newProjectClientName, setNewProjectClientName] = useState("");
  const [newProjectDescription, setNewProjectDescription] = useState("");
  const [workflowName, setWorkflowName] = useState("");
  const [selectedWorkflowId, setSelectedWorkflowId] = useState<number | null>(null);
  const [redesignInstructions, setRedesignInstructions] = useState<Partial<Record<MarketplaceImageRole, string>>>({});
  const [specificationProofreadOutputs, setSpecificationProofreadOutputs] = useState<Set<string>>(() => new Set());
  const [structuredDimensions, setStructuredDimensions] = useState(() => parseMarketplaceDimensions(productBrief.dimensions));
  const emittedDimensionsRef = useRef(productBrief.dimensions);
  const suite = getMarketplaceSuite(channel);
  const definition = MARKETPLACE_CHANNELS[channel];
  const creditCost = getMarketplaceSuiteCreditCost(selectedRoles);
  const activeBrandPreset = brandPresets.find((preset) => preset.id === activeBrandPresetId);
  const activeProject = projects.find((project) => project.id === selectedProjectId);
  const lifestyleRecommendationStatus = getMarketplaceLifestyleRecommendationStatus({
    currentStyle: lifestyleStyle,
    recommendation: lifestyleRecommendation,
    merchantSelected: lifestyleStyleIsMerchantSelected,
  });
  const hasConfirmedCore = productBrief.productName.trim().length > 0 && productBrief.summary.trim().length > 0;
  const detailSpecificationLines = useMemo(() => getMarketplaceDetailSpecificationLines(productBrief), [productBrief]);
  const workspaceStage = getMarketplaceWorkspaceStage({ referenceCount: referenceImages.length, hasConfirmedProduct: hasConfirmedCore, isGenerating, hasResult: Boolean(result) });
  const workspaceSteps = [{ key: "upload" as const, label: "上載" }, { key: "review" as const, label: "核對" }, { key: "generate" as const, label: result ? "完成" : "建立" }];
  const updateBrief = (patch: Partial<MarketplaceProductBrief>) => onProductBriefChange({ ...productBrief, ...patch });
  const updateStructuredDimensions = (patch: Partial<Pick<typeof structuredDimensions, "length" | "width" | "height" | "unit">>) => {
    const next = { ...structuredDimensions, ...patch, isStructured: true };
    const dimensions = formatMarketplaceDimensions(next);
    setStructuredDimensions(next);
    emittedDimensionsRef.current = dimensions;
    updateBrief({ dimensions });
  };
  const toggleRole = (role: MarketplaceImageRole) => onSelectedRolesChange(selectedRoles.includes(role) ? selectedRoles.filter((current) => current !== role) : [...selectedRoles, role]);
  const chooseFiles = (event: React.ChangeEvent<HTMLInputElement>) => { onReferencesSelected(Array.from(event.target.files || [])); event.currentTarget.value = ""; };
  const addRevisionShortcut = (instruction: string) => {
    onDraftRevisionInstructionChange(appendMarketplaceRevisionInstruction(draftRevisionInstruction, instruction));
    window.setTimeout(() => revisionInputRef.current?.focus(), 0);
  };
  const comparisonSnapshot = useMemo(() => {
    return draftHistory.find((snapshot) => snapshot.id === compareSnapshotId) ?? draftHistory.find((snapshot) => compareMarketplaceProductBriefs(snapshot.brief, productBrief).length > 0) ?? draftHistory[0] ?? null;
  }, [compareSnapshotId, draftHistory, productBrief]);
  const draftDifferences = useMemo(() => comparisonSnapshot ? compareMarketplaceProductBriefs(comparisonSnapshot.brief, productBrief) : [], [comparisonSnapshot, productBrief]);
  const editableListingCopy: MarketplaceListingCopy = listingCopy ?? { channel, title: "", bullets: ["", "", "", "", ""], reviewNotes: [] };
  const thailandRequirements = getThailandMarketplaceListingRequirements(channel);
  const thailandFields = normaliseThailandMarketplaceListingFields(editableListingCopy.thailandFields, channel);
  const titleCharacterStatus = getThailandMarketplaceListingCharacterStatus(channel, "title", editableListingCopy.title);
  const descriptionCharacterStatus = getThailandMarketplaceListingCharacterStatus(channel, "description", thailandFields?.description ?? "");
  const newProjectState = getMarketplaceProjectQuickCreateState({ name: newProjectName, clientName: newProjectClientName, description: newProjectDescription });
  const updateListingCopy = (patch: Partial<MarketplaceListingCopy>) => onListingCopyChange({
    ...editableListingCopy,
    ...patch,
    channel,
    bullets: patch.bullets ?? editableListingCopy.bullets,
    reviewNotes: patch.reviewNotes ?? editableListingCopy.reviewNotes,
  });
  const updateThailandFields = (patch: Partial<ThailandMarketplaceListingFields>) => {
    if (!thailandFields) return;
    updateListingCopy({ thailandFields: { ...thailandFields, ...patch } });
  };
  const createAndSelectProject = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!newProjectState.canCreate || isCreatingProject) return;
    await onCreateProject({ name: newProjectState.name, clientName: newProjectState.clientName, description: newProjectState.description });
    setNewProjectName("");
    setNewProjectClientName("");
    setNewProjectDescription("");
  };

  useEffect(() => {
    const hasNewResult = Boolean(result?.outputs.length) && result !== previousResultRef.current;
    previousResultRef.current = result;
    if (!hasNewResult) return;
    window.setTimeout(() => resultSectionRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 80);
  }, [result]);

  useEffect(() => {
    if (productBrief.dimensions === emittedDimensionsRef.current) return;
    emittedDimensionsRef.current = productBrief.dimensions;
    setStructuredDimensions(parseMarketplaceDimensions(productBrief.dimensions));
  }, [productBrief.dimensions]);

  return <Dialog open={open} onOpenChange={onOpenChange}>
    <DialogContent className="inset-0 h-[100svh] max-h-none w-screen max-w-none translate-x-0 translate-y-0 overflow-y-auto rounded-none border-0 bg-[#f8fbff] p-4 data-[state=open]:slide-in-from-bottom-3 sm:inset-auto sm:max-h-[92svh] sm:w-[min(96vw,72rem)] sm:max-w-6xl sm:-translate-x-1/2 sm:-translate-y-1/2 sm:rounded-2xl sm:border sm:border-[#bcd2ec] sm:p-6">
      <DialogHeader className="sticky top-0 z-20 -mx-4 -mt-4 border-b border-[#d5e3f0] bg-[#f8fbff]/95 px-4 pb-3 pt-4 backdrop-blur sm:-mx-6 sm:-mt-6 sm:px-6 sm:pt-6">
        <DialogTitle className="flex items-center gap-2 pr-8 text-[#10213b]"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#e7f0ff] text-[#1665d8]"><Sparkles size={17} /></span>建立商品圖片</DialogTitle>
        <DialogDescription className="mt-1 text-[11px] leading-4 text-[#627188]">上載相片 → 核對 AI 草稿 → 建立圖片。其餘設定只在需要時展開。</DialogDescription>
        <div className="mt-2 flex items-center gap-1.5 text-[10px] font-bold">{workspaceSteps.map((step, index) => { const state = getMarketplaceWorkspaceStepState(workspaceStage, step.key); return <span key={step.key} className={`rounded-full px-2 py-1 ${state === "complete" ? "bg-[#e3f7eb] text-[#197250]" : state === "current" ? "bg-[#e8f3ff] text-[#176bd2]" : "bg-[#edf1f5] text-[#718197]"}`}>{state === "complete" ? <Check className="mr-0.5 inline" size={10} /> : null}{index + 1} {step.label}</span>; })}</div>
      </DialogHeader>

      {isAuthenticated && <details className="mt-4 rounded-xl border border-[#c9dff4] bg-white/80 p-3">
        <summary className="flex cursor-pointer list-none items-center gap-2 text-xs font-bold text-[#315c8b]"><span className="grid h-7 w-7 place-items-center rounded-lg bg-[#e8f3ff] text-[#176bd2]"><Database size={14} /></span>更多設定：流程、品牌、專案與 SKU<span className="ml-auto text-[10px] font-medium text-[#74849a]">需要才展開</span></summary>
        <div className="mt-3 space-y-3">
      <section className="rounded-xl border border-[#d0e2f3] bg-[#f7fbff] p-3">
        <div className="flex items-start gap-2"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-lg bg-white text-[#176bd2] shadow-sm"><History size={14} /></span><div><span className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">常用工作流程</span><p className="mt-0.5 text-[10px] leading-4 text-[#667c95]">儲存平台、所選圖片、情境風格、品牌與專案設定；不會儲存產品相片、SKU 或產品資料。</p></div></div>
        <div className="mt-3 grid gap-2 sm:grid-cols-[1fr_auto_auto]"><select value={selectedWorkflowId ? String(selectedWorkflowId) : ""} onChange={(event) => setSelectedWorkflowId(event.target.value ? Number(event.target.value) : null)} className="h-8 rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-semibold text-[#40536d] outline-none focus:border-[#6ba1e2]"><option value="">選擇已儲存流程</option>{workflows.map((workflow) => <option key={workflow.id} value={workflow.id}>{workflow.name} · {MARKETPLACE_CHANNELS[workflow.channel].label}</option>)}</select><Button type="button" variant="outline" disabled={!selectedWorkflowId} onClick={() => { const workflow = workflows.find((entry) => entry.id === selectedWorkflowId); if (workflow) onApplyWorkflow(workflow); }} className="h-8 rounded-lg border-[#a9c9ee] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]"><RotateCcw size={13} />套用</Button><Button type="button" variant="ghost" disabled={!selectedWorkflowId} onClick={() => { const workflow = workflows.find((entry) => entry.id === selectedWorkflowId); if (workflow) onRemoveWorkflow(workflow); }} className="h-8 rounded-lg px-2 text-[11px] font-bold text-[#7c5360] hover:bg-[#fff1f2]"><Trash2 size={13} />刪除</Button></div>
        <div className="mt-2 flex flex-wrap gap-2"><input value={workflowName} maxLength={60} onChange={(event) => setWorkflowName(event.target.value)} placeholder="例如：Lazada 家居產品四圖" className="h-8 min-w-0 flex-1 rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-medium text-[#40536d] outline-none placeholder:text-[#9aabbc] focus:border-[#6ba1e2]" /><Button type="button" disabled={!workflowName.trim() || isSavingWorkflow} onClick={() => void onSaveWorkflow(workflowName).then((saved) => { if (saved) setWorkflowName(""); })} className="h-8 rounded-lg bg-[#176bd2] px-2.5 text-[11px] font-bold text-white hover:bg-[#1059b8]">{isSavingWorkflow ? <Loader2 className="animate-spin" size={13} /> : <History size={13} />}儲存目前設定</Button></div>
      </section>

      <div className="flex flex-wrap items-center gap-3 rounded-xl border border-[#c9dff4] bg-[#f0f7ff] p-3">
        <span className="grid h-8 w-8 place-items-center rounded-lg text-white" style={{ backgroundColor: activeBrandPreset?.accentColor ?? brandStyle.accentColor }}><Palette size={16} /></span>
        <div className="min-w-0 flex-1"><label htmlFor="suite-brand-preset" className="block text-[10px] font-bold tracking-[0.1em] text-[#3974bf]">套用品牌預設</label><select id="suite-brand-preset" value={activeBrandPresetId ? String(activeBrandPresetId) : ""} onChange={(event) => onBrandPresetChange(event.target.value ? Number(event.target.value) : null)} className="mt-1 h-8 max-w-full rounded-lg border border-[#bfd5ee] bg-white px-2 text-xs font-bold text-[#38546f] outline-none focus:border-[#6ba1e2]">{brandPresets.length === 0 && <option value="">未設定品牌</option>}{brandPresets.map((preset) => <option value={preset.id} key={preset.id}>{preset.isDefault === 1 ? "★ " : ""}{preset.name}</option>)}</select><span className="ml-2 text-[10px] text-[#708198]">{activeBrandPreset?.logoUrl ? "Logo 僅供輔助圖參考" : "可於管理頁加入 Logo"}</span></div>
        {activeBrandPreset?.logoUrl && <img src={activeBrandPreset.logoUrl} alt={`${activeBrandPreset.name} Logo`} className="h-9 w-16 rounded-lg border border-[#d7e4ef] bg-white object-contain" />}
        <Button type="button" variant="outline" onClick={onManageBrandPresets} className="h-8 rounded-lg border-[#b8d0ec] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]"><Palette size={13} />管理品牌</Button>
      </div>

      <section className="rounded-xl border border-[#c9dff4] bg-[#f3f9ff] p-3">
        <div className="flex items-start gap-2"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-lg bg-white text-[#176bd2] shadow-sm"><Database size={14} /></span><div><span className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">專案 SKU 資料庫</span><p className="mt-0.5 text-[10px] leading-4 text-[#667c95]">只儲存已確認資料；同一 SKU 再次使用時可直接套用。</p></div></div>
        <div className="mt-3 grid gap-2 sm:grid-cols-[1fr_0.8fr_auto]"><label className="text-[10px] font-bold text-[#526b87]">儲存到專案<select value={selectedProjectId ? String(selectedProjectId) : ""} onChange={(event) => onProjectChange(event.target.value ? Number(event.target.value) : null)} className="mt-1 h-8 w-full rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-semibold text-[#40536d] outline-none focus:border-[#6ba1e2]"><option value="">請選擇專案</option>{projects.map((project) => <option key={project.id} value={String(project.id)}>{getProjectOptionLabel(project)}</option>)}</select></label><label className="text-[10px] font-bold text-[#526b87]">SKU<input value={sku} maxLength={80} onChange={(event) => onSkuChange(event.target.value)} placeholder="例如：BOX-BLK-01" className="mt-1 h-8 w-full rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-medium text-[#40536d] outline-none focus:border-[#6ba1e2]" /></label><Button type="button" onClick={onSaveProduct} disabled={!selectedProjectId || !sku.trim() || !hasConfirmedCore || isSavingProduct} className="mt-auto h-8 rounded-lg bg-[#176bd2] px-3 text-[11px] font-bold text-white hover:bg-[#1059b8]">{isSavingProduct ? <Loader2 className="animate-spin" size={13} /> : <Database size={13} />}儲存 SKU</Button></div>
        <form onSubmit={(event) => { void createAndSelectProject(event); }} className="mt-2 rounded-lg border border-dashed border-[#b9d4ed] bg-white/75 p-2">
          <div className="grid gap-2 sm:grid-cols-3"><label className="min-w-0 text-[10px] font-bold text-[#526b87]">沒有專案？直接新增<input value={newProjectName} maxLength={60} disabled={isCreatingProject} onChange={(event) => setNewProjectName(event.target.value)} placeholder="例如：秋季新品上架" className="mt-1 h-8 w-full rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-medium text-[#40536d] outline-none placeholder:text-[#9aabbc] focus:border-[#6ba1e2] disabled:bg-[#f4f7fa]" /></label><label className="min-w-0 text-[10px] font-bold text-[#526b87]">客戶名稱（選填）<input value={newProjectClientName} maxLength={60} disabled={isCreatingProject} onChange={(event) => setNewProjectClientName(event.target.value)} placeholder="例如：Juno Store" className="mt-1 h-8 w-full rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-medium text-[#40536d] outline-none placeholder:text-[#9aabbc] focus:border-[#6ba1e2] disabled:bg-[#f4f7fa]" /></label><label className="min-w-0 text-[10px] font-bold text-[#526b87]">簡短說明（選填）<input value={newProjectDescription} maxLength={160} disabled={isCreatingProject} onChange={(event) => setNewProjectDescription(event.target.value)} placeholder="例如：日本秋季新品素材" className="mt-1 h-8 w-full rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-medium text-[#40536d] outline-none placeholder:text-[#9aabbc] focus:border-[#6ba1e2] disabled:bg-[#f4f7fa]" /></label></div>
          <div className="mt-2 flex items-center justify-between gap-2"><p className="text-[10px] leading-4 text-[#74849a]">客戶名稱與說明只用於帳戶內整理，不會寫入 AI 商品資料。</p>
          <Button type="submit" disabled={!newProjectState.canCreate || isCreatingProject} variant="outline" className="h-8 shrink-0 rounded-lg border-[#9fc5eb] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#eaf4ff]">{isCreatingProject ? <Loader2 className="animate-spin" size={13} /> : <FolderPlus size={13} />}新增並選取</Button>
          </div>
        </form>
        {activeProject && (activeProject.clientName || activeProject.description) && <p className="mt-2 rounded-lg bg-[#eaf5ff] px-2.5 py-1.5 text-[10px] leading-4 text-[#52708e]"><strong className="text-[#2e659e]">目前專案：</strong>{activeProject.clientName ? `${activeProject.clientName} · ` : ""}{activeProject.description || "未填寫說明"}</p>}
        {selectedProjectId ? <div className="mt-3"><div className="flex items-center justify-between"><span className="text-[10px] font-bold text-[#52708e]">此專案已儲存的產品</span><span className="text-[10px] text-[#74849a]">{savedProducts.length} 個 SKU</span></div>{savedProducts.length ? <div className="mt-2 flex max-h-24 flex-wrap gap-1.5 overflow-y-auto">{savedProducts.map((product) => <button type="button" key={product.id} onClick={() => onLoadSavedProduct(product)} className="rounded-lg border border-[#bdd4ed] bg-white px-2 py-1.5 text-left text-[10px] font-bold text-[#2b5f94] hover:bg-[#eaf4ff]"><span className="mr-1 text-[#176bd2]">{product.sku}</span><span className="font-medium text-[#667c95]">{product.productName}</span></button>)}</div> : <p className="mt-1.5 text-[10px] text-[#74849a]">暫未儲存 SKU；確認目前資料後即可建立第一個。</p>}</div> : <p className="mt-2 text-[10px] text-[#74849a]">請選擇專案後，才可保存或重用 SKU 資料。</p>}
      </section>
        </div>
      </details>}

      <div className="grid gap-5 xl:grid-cols-[0.86fr_1.14fr]">
        <section className="space-y-4 rounded-2xl border border-[#d4e2f0] bg-white p-4 shadow-sm">
          <div><span className="text-[11px] font-bold tracking-[0.12em] text-[#3974bf]">01 · 銷售平台</span><label className="mt-2 flex items-center gap-2 rounded-xl border border-[#bcd4ee] bg-[#f4f9ff] p-2 sm:hidden"><ListChecks size={16} className="shrink-0 text-[#176bd2]" /><select value={channel} onChange={(event) => onChannelChange(event.target.value as MarketplaceChannel)} className="h-8 min-w-0 flex-1 bg-transparent text-xs font-bold text-[#294b70] outline-none">{(Object.keys(MARKETPLACE_CHANNELS) as MarketplaceChannel[]).map((key) => <option value={key} key={key}>{MARKETPLACE_CHANNELS[key].label}</option>)}</select></label><div className="mt-2 hidden grid-cols-2 gap-2 sm:grid sm:grid-cols-3">{(Object.keys(MARKETPLACE_CHANNELS) as MarketplaceChannel[]).map((key) => <button key={key} type="button" onClick={() => onChannelChange(key)} className={`min-h-12 rounded-xl border px-2 text-left text-xs font-bold transition ${channel === key ? "border-[#2e72d7] bg-[#eaf3ff] text-[#125ec8] shadow-sm" : "border-[#d8e3ef] bg-white text-[#4d627c] hover:border-[#9dc1ef]"}`}><span className="block leading-4">{MARKETPLACE_CHANNELS[key].label}</span><span className="mt-0.5 block text-[10px] font-medium opacity-75">{MARKETPLACE_CHANNELS[key].recommendedSize}</span></button>)}</div></div>

          <div><span className="text-[11px] font-bold tracking-[0.12em] text-[#3974bf]">02 · 上載產品參考圖</span><input ref={fileInputRef} type="file" multiple accept="image/jpeg,image/png,image/webp,image/heic,image/heif" className="sr-only" onChange={chooseFiles} /><button type="button" onClick={() => fileInputRef.current?.click()} className="mt-2 grid min-h-28 w-full place-items-center rounded-2xl border border-dashed border-[#aac6e4] bg-[#f6faff] text-center transition hover:border-[#4d8fe6] hover:bg-[#edf5ff]"><span className="p-4"><span className="mx-auto grid h-9 w-9 place-items-center rounded-xl bg-white text-[#236ed0] shadow-sm"><Upload size={18} /></span><strong className="mt-2 block text-sm text-[#28415e]">{referenceImages.length ? "更換參考相片" : "上載產品相片"}</strong><span className="mt-1 block text-[11px] leading-5 text-[#6c7c91]">最多 3 張：主角度＋細節／側面<br />JPG、PNG、WEBP 或 HEIC</span></span></button>{referenceImages.length > 0 && <div className="mt-2 grid grid-cols-3 gap-2">{referenceImages.map((reference, index) => <div key={`${reference.previewUrl}-${index}`} className="group relative overflow-hidden rounded-xl border border-[#d5e3ef] bg-[#f5f8fb]"><img src={reference.previewUrl} alt={`${index === 0 ? "主參考圖" : `參考角度 ${index + 1}`}：${reference.fileName}`} className="aspect-square w-full object-contain" /><span className="absolute left-1 top-1 rounded-md bg-[#12385f]/85 px-1.5 py-0.5 text-[9px] font-bold text-white">{index === 0 ? "主參考" : `角度 ${index + 1}`}</span><button type="button" aria-label={`移除 ${reference.fileName}`} onClick={() => onRemoveReference(index)} className="absolute right-1 top-1 grid h-6 w-6 place-items-center rounded-md bg-white/95 text-[#a94a35] opacity-100 shadow-sm transition sm:opacity-0 sm:group-hover:opacity-100"><Trash2 size={13} /></button><p className="truncate px-1.5 py-1 text-[9px] text-[#53677e]">{reference.fileName}</p></div>)}</div>}<p className="mt-2 text-[10px] leading-4 text-[#74839a]">第一張是儲存到相片庫的主參考；其餘角度只用於本次 AI 核對，不會額外保存或計入儲存空間。</p>{referenceImages.some((reference) => reference.quality) && <div className="mt-3 rounded-xl border border-[#c9def2] bg-white p-2.5"><div className="flex items-start gap-2"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-lg bg-[#e8f4ff] text-[#176bd2]"><CheckCircle2 size={14} /></span><div><strong className="block text-[11px] text-[#294b70]">參考圖快速檢查</strong><p className="mt-0.5 text-[10px] leading-4 text-[#6b7d92]">檢查解析度、壓縮與畫面訊號；只作生成前提示，不會分析或改動你的產品資料。</p></div></div><div className="mt-2 space-y-1.5">{referenceImages.map((reference, index) => reference.quality && <div key={`quality-${reference.previewUrl}`} className={`rounded-lg border px-2 py-1.5 text-[10px] leading-4 ${reference.quality.readiness === "ready" ? "border-[#cce9db] bg-[#f5fcf8] text-[#39725d]" : "border-[#f0d4a7] bg-[#fffaf2] text-[#765426]"}`}><div className="flex items-center justify-between gap-2"><strong>{index === 0 ? "主參考圖" : `參考角度 ${index + 1}`} · {reference.quality.width}×{reference.quality.height}</strong><span className="shrink-0 font-bold">{reference.quality.readiness === "ready" ? "基本合適" : "建議留意"}</span></div><p className="mt-0.5">{reference.quality.summary}</p>{reference.quality.notices.map((notice) => <p className="mt-0.5" key={notice}>• {notice}</p>)}</div>)}</div></div>}</div>

          <div className="rounded-xl border border-[#d6e5f4] bg-[#f5faff] p-3">
            <div className="flex items-start justify-between gap-3"><div><span className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">03 · AI 草擬產品資料</span><p className="mt-1 text-[10px] leading-4 text-[#667c95]">根據所有參考角度提出描述及待核對事項；不會扣除圖片額度。</p></div><Button type="button" variant="outline" onClick={onDraft} disabled={!referenceImages.length || isDrafting} className="h-8 shrink-0 rounded-lg border-[#a9c9ee] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]">{isDrafting ? <><Loader2 className="animate-spin" size={13} />分析中</> : <><Sparkles size={13} />重新草擬</>}</Button></div>
            {isDrafting && <div className="mt-3 rounded-lg border border-[#c7ddf5] bg-white p-2.5"><div className="flex items-center justify-between gap-3 text-[10px] font-bold text-[#3b638f]"><span className="flex items-center gap-1.5"><Clock3 size={12} />正在讀取相片、整理可核實資料</span><span>{draftElapsed}</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#e1edf8]"><div className="h-full rounded-full bg-[#2c76d5] transition-[width] duration-700" style={{ width: `${draftProgress}%` }} /></div><p className="mt-1.5 text-[10px] text-[#6f8196]">通常約 20–30 秒；關閉此視窗或重新整理頁面前請等待完成。</p></div>}
            {draftFailure && <div role="alert" className="mt-3 rounded-lg border border-[#edc9bd] bg-[#fff8f5] p-2.5 text-[11px] leading-5 text-[#914833]"><AlertTriangle className="mr-1 inline" size={13} /><strong>草擬暫時未完成。</strong>{draftFailure}</div>}
          </div>

          {draftHistory.length > 0 && <details className="rounded-xl border border-[#d9e5f1] bg-white p-3"><summary className="flex cursor-pointer items-center gap-2 text-xs font-bold text-[#36516e]"><History size={14} className="text-[#1d70d2]" />草擬版本與比較（本次工作）<span className="ml-auto text-[10px] font-medium text-[#74849a]">保留最近 {draftHistory.length} 個版本</span></summary><div className="mt-3 space-y-3"><div className="flex flex-wrap gap-2">{draftHistory.map((snapshot, index) => <button type="button" key={snapshot.id} onClick={() => setCompareSnapshotId(snapshot.id)} className={`rounded-lg border px-2 py-1 text-[10px] font-bold ${comparisonSnapshot?.id === snapshot.id ? "border-[#4c8ce2] bg-[#eaf3ff] text-[#176bd2]" : "border-[#d5e3ef] bg-white text-[#65788e] hover:border-[#9bbfe9]"}`}>{index + 1}. {snapshot.name} · {formatDraftTime(snapshot.createdAt)}</button>)}</div>{comparisonSnapshot && <><div className="rounded-lg border border-[#dfe9f3] bg-[#f8fbff] p-2.5 text-[10px] leading-4 text-[#5e728a]">正在比較「{comparisonSnapshot.name}」與目前表單。{draftDifferences.length === 0 ? "兩者內容相同。" : `共有 ${draftDifferences.length} 項差異。`}</div>{draftDifferences.length > 0 && <div className="max-h-40 space-y-2 overflow-y-auto">{draftDifferences.map((difference) => <div key={difference.label} className="grid gap-1 rounded-lg border border-[#e1eaf3] bg-white p-2 text-[10px] sm:grid-cols-[72px_1fr_1fr]"><strong className="text-[#426381]">{difference.label}</strong><span className="text-[#8a5a45]">舊：{difference.before}</span><span className="text-[#28735a]">現：{difference.after}</span></div>)}</div>}<div className="flex flex-wrap items-end gap-2"><label className="grid gap-1 text-[10px] font-bold text-[#526b87]">版本名稱<input value={comparisonSnapshot.name} maxLength={36} onChange={(event) => onRenameDraft(comparisonSnapshot.id, event.target.value)} className="h-8 w-32 rounded-lg border border-[#cdddec] bg-white px-2 text-[11px] font-medium text-[#38546f] outline-none focus:border-[#6ba1e2]" /></label><Button type="button" variant="outline" onClick={() => onRestoreDraft(comparisonSnapshot)} className="h-8 rounded-lg border-[#b8d0ec] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]"><RotateCcw size={13} />還原這個版本</Button><Button type="button" variant="ghost" onClick={onClearDraftHistory} className="h-8 rounded-lg px-2.5 text-[11px] font-bold text-[#64778c] hover:bg-[#eef4fa]"><Trash2 size={13} />清除本次記錄</Button></div></>}</div></details>}
        </section>

        <section className="space-y-4 rounded-2xl border border-[#d4e2f0] bg-[#f4f8fd] p-4">
          <div className="flex flex-wrap items-start justify-between gap-3"><div><span className="text-[11px] font-bold tracking-[0.12em] text-[#3974bf]">04 · 計劃、核實後生成</span><h3 className="mt-1 text-base font-bold text-[#203852]">選擇你要建立的產品圖片</h3><p className="mt-1 text-xs leading-5 text-[#68798e]">{definition.recommendedSize} · {definition.note}</p></div><span className="rounded-full bg-[#e2f7eb] px-3 py-1 text-xs font-bold text-[#197250]">使用 {creditCost} 張額度</span></div>

          {!referenceImages.length ? <div className="rounded-xl border border-dashed border-[#c7d9eb] bg-white p-5 text-center text-xs leading-5 text-[#6c7d91]">先上載一至三張產品參考圖，系統才可以建立可編輯的產品資料草稿。</div> : <div className="space-y-3 rounded-xl border border-[#d8e4f1] bg-white p-3">
            <div className="flex items-center justify-between gap-3 rounded-xl bg-[#f4f9ff] p-2.5"><div className="flex min-w-0 items-center gap-2"><CheckCircle2 size={16} className={hasConfirmedCore ? "shrink-0 text-[#1e9b68]" : "shrink-0 text-[#9dafc0]"} /><div><p className="text-[11px] font-bold text-[#29425f]">{hasConfirmedCore ? "AI 已整理產品資料" : "等待產品資料"}</p><p className="truncate text-[10px] text-[#667c95]">{productBrief.productName || "上載相片後會自動草擬"}</p></div></div><Button type="button" variant="outline" onClick={onDraft} disabled={!referenceImages.length || isDrafting} className="h-8 shrink-0 rounded-lg border-[#a9c9ee] bg-white px-2 text-[10px] font-bold text-[#176bd2] hover:bg-[#edf5ff]">{isDrafting ? <Loader2 className="animate-spin" size={12} /> : <Sparkles size={12} />}{isDrafting ? "分析中" : "重整"}</Button></div>
            <details open={!hasConfirmedCore} className="rounded-xl border border-[#dbe7f2] bg-[#fbfdff] p-2.5"><summary className="flex cursor-pointer list-none items-center gap-2 text-[11px] font-bold text-[#3b638f]"><ListChecks size={14} />{hasConfirmedCore ? "檢視或修改產品資料" : "填寫或確認產品資料"}<span className="ml-auto text-[10px] font-medium text-[#75879b]">需要才展開</span></summary><div className="mt-3 space-y-3"><div className="flex items-center gap-2 text-xs font-bold text-[#29425f]"><CheckCircle2 size={15} className={hasConfirmedCore ? "text-[#1e9b68]" : "text-[#9dafc0]"} />請逐項核對及修改，確認後才生成</div><div className="grid gap-3 sm:grid-cols-2"><div><label htmlFor="marketplace-name" className="text-[10px] font-bold tracking-[0.1em] text-[#3974bf]">產品名稱 *</label><input id="marketplace-name" value={productBrief.productName} maxLength={100} onChange={(event) => updateBrief({ productName: event.target.value })} placeholder="例如：玻璃密封食物盒套裝" className="mt-1.5 h-9 w-full rounded-xl border border-[#d3e0ee] bg-[#fbfdff] px-2.5 text-xs text-[#314963] outline-none focus:border-[#6ba1e2] focus:ring-2 focus:ring-[#e4f0ff]" /></div><div><label htmlFor="marketplace-summary" className="text-[10px] font-bold tracking-[0.1em] text-[#3974bf]">產品描述 *</label><textarea id="marketplace-summary" value={productBrief.summary} maxLength={600} onChange={(event) => updateBrief({ summary: event.target.value })} placeholder="只保留你能核實的產品資料。" className="mt-1.5 min-h-20 w-full resize-y rounded-xl border border-[#d3e0ee] bg-[#fbfdff] p-2.5 text-xs leading-5 text-[#314963] outline-none focus:border-[#6ba1e2] focus:ring-2 focus:ring-[#e4f0ff]" /></div></div><div className="rounded-xl border border-[#d6e5f4] bg-[#f7fbff] p-3">
  <div className="grid gap-3 sm:grid-cols-2">
    <label htmlFor="marketplace-weight" className="text-[10px] font-bold tracking-[0.1em] text-[#3974bf]">產品重量 <span className="font-medium text-[#718197]">（已核實才填）</span><input id="marketplace-weight" value={productBrief.weight} maxLength={80} onChange={(event) => updateBrief({ weight: event.target.value })} placeholder="例如：180 g" className="mt-1.5 h-9 w-full rounded-xl border border-[#d3e0ee] bg-white px-2.5 text-xs text-[#314963] outline-none focus:border-[#6ba1e2] focus:ring-2 focus:ring-[#e4f0ff]" /></label>
    <div className="text-[10px] font-bold tracking-[0.1em] text-[#3974bf]"><span>產品尺寸 L × W × H <span className="font-medium text-[#718197]">（已核實才填）</span></span><div className="mt-1.5 grid grid-cols-[1fr_auto_1fr_auto_1fr_0.8fr] items-end gap-1"><label className="min-w-0"><span className="block text-[9px] font-medium tracking-normal text-[#718197]">長</span><input aria-label="產品長度" inputMode="decimal" value={structuredDimensions.length} maxLength={12} onChange={(event) => updateStructuredDimensions({ length: event.target.value })} placeholder="12" className="mt-1 h-9 w-full rounded-xl border border-[#d3e0ee] bg-white px-2 text-center text-xs text-[#314963] outline-none focus:border-[#6ba1e2]" /></label><span className="pb-2 text-xs text-[#7890aa]">×</span><label className="min-w-0"><span className="block text-[9px] font-medium tracking-normal text-[#718197]">闊</span><input aria-label="產品闊度" inputMode="decimal" value={structuredDimensions.width} maxLength={12} onChange={(event) => updateStructuredDimensions({ width: event.target.value })} placeholder="8" className="mt-1 h-9 w-full rounded-xl border border-[#d3e0ee] bg-white px-2 text-center text-xs text-[#314963] outline-none focus:border-[#6ba1e2]" /></label><span className="pb-2 text-xs text-[#7890aa]">×</span><label className="min-w-0"><span className="block text-[9px] font-medium tracking-normal text-[#718197]">高</span><input aria-label="產品高度" inputMode="decimal" value={structuredDimensions.height} maxLength={12} onChange={(event) => updateStructuredDimensions({ height: event.target.value })} placeholder="4" className="mt-1 h-9 w-full rounded-xl border border-[#d3e0ee] bg-white px-2 text-center text-xs text-[#314963] outline-none focus:border-[#6ba1e2]" /></label><label className="min-w-0"><span className="block text-[9px] font-medium tracking-normal text-[#718197]">單位</span><select aria-label="尺寸單位" value={structuredDimensions.unit} onChange={(event) => updateStructuredDimensions({ unit: event.target.value as typeof structuredDimensions.unit })} className="mt-1 h-9 w-full rounded-xl border border-[#d3e0ee] bg-white px-1 text-center text-xs font-bold text-[#314963] outline-none focus:border-[#6ba1e2]"><option value="mm">mm</option><option value="cm">cm</option><option value="m">m</option><option value="in">in</option></select></label></div></div>
  </div>
  {!structuredDimensions.isStructured && productBrief.dimensions.trim() && <p className="mt-2 rounded-lg border border-[#efd4a6] bg-[#fffaf1] px-2.5 py-1.5 text-[10px] leading-4 text-[#805926]"><AlertTriangle className="mr-1 inline" size={12} />現有尺寸格式未能拆分；請重新輸入長、闊、高及單位，才可用於規格圖。</p>}
  <p className="mt-2 text-[10px] leading-4 text-[#718197]">AI 只會在相片上可清楚核實時草擬；你可手動修正。填妥後，第三張「核實賣點圖」才會顯示這兩項已確認資料。</p>
  {selectedRoles.includes("detail") && detailSpecificationLines.length > 0 && <div className="mt-3 border-t border-[#dbe8f4] pt-3"><div className="flex items-start gap-2"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-lg bg-white text-[#176bd2] shadow-sm"><LayoutGrid size={14} /></span><div><p className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">第三張規格圖版面</p><p className="mt-0.5 text-[10px] leading-4 text-[#667c95]">只影響「核實賣點圖」；以下是版面方向預覽，實際排字仍須在成品逐字核對。</p></div></div><div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-4">{(Object.entries(MARKETPLACE_DETAIL_SPECIFICATION_LAYOUTS) as Array<[MarketplaceDetailSpecificationLayout, typeof MARKETPLACE_DETAIL_SPECIFICATION_LAYOUTS[MarketplaceDetailSpecificationLayout]]>).map(([layout, option]) => { const selected = detailSpecificationLayout === layout; return <button type="button" key={layout} aria-pressed={selected} onClick={() => onDetailSpecificationLayoutChange(layout)} className={`rounded-xl border p-2 text-left transition ${selected ? "border-[#3a7fda] bg-[#eaf3ff] shadow-sm" : "border-[#d8e4f1] bg-white hover:border-[#9bc1ed]"}`}><span className="relative mb-1.5 block h-12 overflow-hidden rounded-lg border border-[#d7e4ef] bg-[#f9fbfd]"><span className={`absolute rounded bg-[#78a9e4] ${layout === "side_card" ? "bottom-2 left-2 top-2 w-1/2" : layout === "dimension_guide" ? "bottom-2 left-4 top-2 w-1/2" : "bottom-4 left-5 right-5 top-2"}`} /><span className={`absolute rounded bg-[#d4e5f7] ${layout === "side_card" ? "bottom-3 right-2 top-3 w-[30%]" : layout === "dimension_guide" ? "bottom-2 right-2 top-2 w-1/4" : layout === "bottom_strip" ? "bottom-1.5 left-2 right-2 h-2" : "bottom-2 left-2 right-2 h-2"}`} />{layout === "dimension_guide" && <span className="absolute bottom-3 left-1 right-1 border-t border-dashed border-[#4f8dd8]" />}</span><strong className="block text-[10px] text-[#29425f]">{option.label}</strong><span className="mt-0.5 block text-[9px] leading-3 text-[#718197]">{option.description}</span></button>; })}</div></div>}
</div><div className="grid gap-3 sm:grid-cols-3"><BriefLinesEditor id="marketplace-facts" label="確認資料" value={productBrief.confirmedFacts} onChange={(confirmedFacts) => updateBrief({ confirmedFacts })} placeholder="例如：透明蓋、黑色扣件" /><BriefLinesEditor id="marketplace-highlights" label="可用於賣點圖的核實資料" value={productBrief.visualHighlights} onChange={(visualHighlights) => updateBrief({ visualHighlights })} placeholder="例如：附帶 3 個不同容量盒" /><BriefLinesEditor id="marketplace-usage" label="可接受的使用情境" value={productBrief.usageIdeas} onChange={(usageIdeas) => updateBrief({ usageIdeas })} placeholder="例如：家居食物收納" /></div>{productBrief.reviewQuestions.length > 0 && <div className="rounded-lg border border-[#f0d4a7] bg-[#fffaf2] p-2.5 text-[11px] leading-5 text-[#745123]"><AlertTriangle className="mr-1 inline text-[#bd7a0f]" size={13} /><strong>請先核對：</strong>{productBrief.reviewQuestions.map((question) => <span className="block pl-5" key={question}>• {question}</span>)}</div>}<p className="text-[10px] leading-4 text-[#74839a]">若要做尺寸、功能或組合資訊圖，請把<strong>已核實</strong>的文字／數字逐項填在「可用於賣點圖的核實資料」。留空時系統只會做無文字細節圖，絕不猜測。</p><div className="rounded-xl border border-[#bfdcf5] bg-[#f4f9ff] p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div><span className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">不滿意？告訴 AI 要怎樣修改</span><p className="mt-1 text-[10px] leading-4 text-[#667c95]">例如「名稱改成較簡潔」、「刪除未能確認的健康描述」。目前內容會保留為可比較版本。</p></div><Button type="button" variant="outline" onClick={onDraft} disabled={!draftRevisionInstruction.trim() || isDrafting} className="h-8 shrink-0 rounded-lg border-[#a9c9ee] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]">{isDrafting ? <><Loader2 className="animate-spin" size={13} />更新中</> : <><Sparkles size={13} />按要求更新</>}</Button></div><textarea ref={revisionInputRef} id="marketplace-draft-revision" value={draftRevisionInstruction} maxLength={500} onChange={(event) => onDraftRevisionInstructionChange(event.target.value)} disabled={isDrafting} placeholder="請描述想保留、刪除或改寫的地方；未能由相片或你提供的資料核實的內容，AI 會改列為待核對事項。" className="mt-2 min-h-[74px] w-full resize-y rounded-lg border border-[#cbddec] bg-white p-2.5 text-xs leading-5 text-[#314963] outline-none placeholder:text-[#93a4b8] focus:border-[#6ba1e2] focus:ring-2 focus:ring-[#e4f0ff] disabled:bg-[#f5f7fa]" /><div className="mt-2 flex flex-wrap items-center gap-1.5"><span className="mr-1 text-[10px] font-bold text-[#58708b]">常用修改：</span>{MARKETPLACE_DRAFT_REVISION_SHORTCUTS.map((shortcut) => <button type="button" key={shortcut.label} onClick={() => addRevisionShortcut(shortcut.instruction)} disabled={isDrafting} className="rounded-full border border-[#b8d3ef] bg-white px-2.5 py-1 text-[10px] font-bold text-[#176bd2] transition hover:border-[#75a8df] hover:bg-[#eaf4ff] disabled:cursor-not-allowed disabled:opacity-60">{shortcut.label}</button>)}</div><p className="mt-1.5 text-[10px] text-[#718197]">快捷鍵會加入欄位，仍可自行修改；只修改草稿，不會扣除圖片額度。AI 不會把要求直接當成產品規格、功效、認證或包裝數量。</p></div></div></details></div>}

          <details className="rounded-xl border border-[#cce0f3] bg-[#f7fbff] p-3"><summary className="flex cursor-pointer list-none items-center gap-2 text-xs font-bold text-[#315c8b]"><ListChecks size={14} />上架文案與匯出<span className="ml-auto text-[10px] font-medium text-[#74849a]">選填</span></summary><div className="mt-3 rounded-xl border border-[#cce0f3] bg-[#f1f8ff] p-3">
            <div className="flex flex-wrap items-start justify-between gap-3"><div><span className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">05 · AI 上架文案（選填）</span><p className="mt-1 text-[10px] leading-4 text-[#667c95]">按已確認的產品資料，為 {definition.label} 建議商品標題及五點描述；不扣圖片額度。</p></div><Button type="button" variant="outline" disabled={!hasConfirmedCore || isListingCopyDrafting} onClick={onDraftListingCopy} className="h-8 rounded-lg border-[#a9c9ee] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]">{isListingCopyDrafting ? <><Loader2 className="animate-spin" size={13} />生成中</> : <><ListChecks size={13} />生成上架文案</>}</Button></div>
            <div className="mt-3 grid gap-2">
              <label className="text-[10px] font-bold tracking-[0.1em] text-[#3974bf]">建議商品標題<input value={editableListingCopy.title} maxLength={thailandRequirements?.titleLimit ?? 180} onChange={(event) => updateListingCopy({ title: event.target.value })} placeholder="先確認產品資料，再生成文案" className="mt-1 h-9 w-full rounded-xl border border-[#cdddec] bg-white px-2.5 text-xs text-[#314963] outline-none focus:border-[#6ba1e2] focus:ring-2 focus:ring-[#e4f0ff]" /></label>
              {titleCharacterStatus && <p className={`text-right text-[10px] ${titleCharacterStatus.overLimit ? "font-bold text-[#b64732]" : "text-[#718197]"}`}>{titleCharacterStatus.length}/{titleCharacterStatus.limit} 字元 · 尚餘 {titleCharacterStatus.remaining}</p>}
              <div className="grid gap-2 sm:grid-cols-2">{[0, 1, 2, 3, 4].map((index) => <label className="text-[10px] font-bold text-[#526b87]" key={index}>五點描述 {index + 1}<input value={editableListingCopy.bullets[index] ?? ""} maxLength={240} onChange={(event) => { const bullets = [...editableListingCopy.bullets]; bullets[index] = event.target.value; updateListingCopy({ bullets }); }} className="mt-1 h-8 w-full rounded-lg border border-[#d3e0ee] bg-white px-2 text-[11px] font-medium text-[#425b76] outline-none focus:border-[#6ba1e2]" /></label>)}</div>
              {thailandRequirements && thailandFields && <section className="rounded-xl border border-[#b9d9ed] bg-white p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div><span className="text-[11px] font-bold tracking-[0.1em] text-[#18715c]">泰國平台專屬欄位</span><p className="mt-1 text-[10px] leading-4 text-[#667c95]">{thailandRequirements.label}：預填後可匯出。必填類目、品牌、屬性與物流資料須以你實際 Seller Center 店舖及類目為準。</p></div><a href={thailandRequirements.sourceUrl} target="_blank" rel="noreferrer" className="text-[10px] font-bold text-[#176bd2] underline underline-offset-2">官方欄位說明</a></div><p className="mt-2 rounded-lg bg-[#eef8f4] p-2 text-[10px] leading-4 text-[#356c5a]">{thailandRequirements.titleHint} {thailandRequirements.descriptionHint}</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{thailandRequirements.fields.map((field) => { const isLongText = field.key === "description" || field.key === "categoryAttributes" || field.key === "whatsInTheBox"; const value = thailandFields[field.key]; const status = field.key === "description" ? descriptionCharacterStatus : null; return <label key={field.key} className={isLongText ? "text-[10px] font-bold text-[#526b87] sm:col-span-2" : "text-[10px] font-bold text-[#526b87]"}>{field.label}{field.required ? " *" : ""}{isLongText ? <textarea value={value} maxLength={field.maxLength} onChange={(event) => updateThailandFields({ [field.key]: event.target.value })} placeholder={field.placeholder} className="mt-1 min-h-20 w-full resize-y rounded-lg border border-[#d3e0ee] bg-[#fbfdff] p-2 text-[11px] leading-5 text-[#425b76] outline-none focus:border-[#6ba1e2]" /> : <input value={value} maxLength={field.maxLength} onChange={(event) => updateThailandFields({ [field.key]: event.target.value })} placeholder={field.placeholder} className="mt-1 h-8 w-full rounded-lg border border-[#d3e0ee] bg-[#fbfdff] px-2 text-[11px] font-medium text-[#425b76] outline-none focus:border-[#6ba1e2]" />}<span className={`mt-1 block font-medium leading-4 ${status?.overLimit ? "text-[#b64732]" : "text-[#74839a]"}`}>{status ? `${status.length}/${status.limit} 字元 · 尚餘 ${status.remaining}。` : field.helper}</span></label>; })}</div><p className="mt-3 rounded-lg border border-[#f0d4a7] bg-[#fffaf2] p-2 text-[10px] leading-4 text-[#745123]"><AlertTriangle className="mr-1 inline text-[#bd7a0f]" size={12} />{thailandRequirements.verificationNote}</p></section>}
              {editableListingCopy.reviewNotes.length > 0 && <div className="rounded-lg border border-[#f0d4a7] bg-[#fffaf2] p-2 text-[10px] leading-4 text-[#745123]"><AlertTriangle className="mr-1 inline text-[#bd7a0f]" size={12} /><strong>上架前再核對：</strong>{editableListingCopy.reviewNotes.map((note) => <span className="block pl-4" key={note}>• {note}</span>)}</div>}
              <div className="flex flex-wrap gap-2"><Button type="button" variant="outline" disabled={!hasConfirmedCore} onClick={() => onExportProductData("csv")} className="h-8 rounded-lg border-[#b8d0ec] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]"><Download size={13} />下載 CSV</Button><Button type="button" variant="outline" disabled={!hasConfirmedCore} onClick={() => onExportProductData("xlsx")} className="h-8 rounded-lg border-[#b8d0ec] bg-white px-2.5 text-[11px] font-bold text-[#176bd2] hover:bg-[#edf5ff]"><FileSpreadsheet size={13} />下載 Excel</Button><span className="self-center text-[10px] text-[#718197]">匯出包含已確認資料、待核對事項及目前文案。</span></div>
              <div className="flex flex-wrap gap-2 border-t border-[#d9e7f3] pt-2"><Button type="button" variant="ghost" disabled={!editableListingCopy.title.trim()} onClick={() => onCopyListingText("title")} className="h-7 rounded-lg px-2 text-[10px] font-bold text-[#176bd2] hover:bg-white"><Copy size={12} />複製標題</Button><Button type="button" variant="ghost" disabled={!editableListingCopy.bullets.some((bullet) => bullet.trim())} onClick={() => onCopyListingText("bullets")} className="h-7 rounded-lg px-2 text-[10px] font-bold text-[#176bd2] hover:bg-white"><Copy size={12} />複製五點描述</Button><Button type="button" variant="outline" disabled={!hasConfirmedCore || !sku.trim()} onClick={() => onExportPlatformTemplate("csv")} className="h-7 rounded-lg border-[#b8d0ec] bg-white px-2 text-[10px] font-bold text-[#176bd2] hover:bg-[#edf5ff]"><Download size={12} />{definition.label} 模板 CSV</Button><Button type="button" variant="outline" disabled={!hasConfirmedCore || !sku.trim()} onClick={() => onExportPlatformTemplate("xlsx")} className="h-7 rounded-lg border-[#b8d0ec] bg-white px-2 text-[10px] font-bold text-[#176bd2] hover:bg-[#edf5ff]"><FileSpreadsheet size={12} />模板 Excel</Button></div><p className="text-[10px] leading-4 text-[#718197]">平台模板為預填起始欄位；請下載目標類目最新官方模板後再核對及對應欄位。</p>
            </div>
          </div></details>

          <div><div className="flex items-center justify-between"><span className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">圖片計劃</span><span className="text-[10px] text-[#718197]">點選需要的圖片</span></div><div className="mt-2 grid grid-cols-2 gap-2">{suite.map((item, index) => { const selected = selectedRoles.includes(item.role); return <button key={item.role} type="button" onClick={() => toggleRole(item.role)} className={`relative rounded-xl border p-2.5 text-left transition sm:p-3 ${selected ? "border-[#4c8ce2] bg-[#eaf3ff] shadow-sm" : "border-[#d8e4f1] bg-white opacity-70 hover:opacity-100"}`}><span className={`absolute right-2 top-2 grid h-5 w-5 place-items-center rounded-full border ${selected ? "border-[#2374d6] bg-[#2374d6] text-white" : "border-[#a9bbcf] bg-white text-transparent"}`}><Check size={12} /></span><span className="flex h-5 w-5 items-center justify-center rounded-full bg-white text-[10px] font-bold text-[#1d6bce] shadow-sm">{index + 1}</span><strong className="mt-2 block pr-5 text-[11px] leading-4 text-[#29425f] sm:text-xs">{item.title}</strong><p className="mt-1 hidden text-[11px] leading-4 text-[#6e7f94] sm:block">{item.description}</p>{item.role === "main" && <span className="mt-1 hidden text-[10px] font-bold text-[#2f71bd] sm:block">白底、無文字、不可套用品牌色</span>}</button>; })}</div>{selectedRoles.includes("lifestyle") && <div className="mt-3 rounded-xl border border-[#cbe1d4] bg-[#f4fbf7] p-3">
            <div className="flex items-start gap-2">
              <span className="grid h-7 w-7 shrink-0 place-items-center rounded-lg bg-white text-[#197250] shadow-sm"><Sparkles size={14} /></span>
              <div className="min-w-0 flex-1">
                <label htmlFor="marketplace-lifestyle-style" className="block text-[11px] font-bold tracking-[0.1em] text-[#197250]">情境風格</label>
                <select id="marketplace-lifestyle-style" value={lifestyleStyle} onChange={(event) => onLifestyleStyleChange(event.target.value as MarketplaceLifestyleStyle)} className="mt-2 h-9 w-full rounded-lg border border-[#c5dfcf] bg-white px-2 text-xs font-bold text-[#355b49] outline-none focus:border-[#55a77d] focus:ring-2 focus:ring-[#e1f4e8]">
                  {Object.entries(MARKETPLACE_LIFESTYLE_STYLES).map(([value, style]) => <option value={value} key={value}>{style.label}</option>)}
                </select>
                <p className="mt-1.5 text-[10px] text-[#5e7b6d]">只用於情境圖背景。</p>

                {lifestyleRecommendation && <div className="mt-3 rounded-xl border border-[#b9ddc8] bg-white/90 p-2.5">
                  <div className="flex items-center justify-between gap-2"><p className="text-[10px] font-bold tracking-[0.08em] text-[#237157]">AI 建議場景</p><Button type="button" variant="outline" onClick={onApplyLifestyleRecommendation} disabled={lifestyleRecommendationStatus === "applied" && selectedLifestyleScene?.id === lifestyleRecommendation.candidates[0]?.id} className="h-7 shrink-0 rounded-lg border-[#9dccaf] bg-white px-2 text-[10px] font-bold text-[#197250] hover:bg-[#edf9f1] disabled:opacity-60">{lifestyleRecommendationStatus === "applied" && selectedLifestyleScene?.id === lifestyleRecommendation.candidates[0]?.id ? <><Check size={11} />已採用</> : <><Sparkles size={11} />首選</>}</Button></div>
                  <div className="mt-2 grid gap-1.5 sm:grid-cols-2">{lifestyleRecommendation.candidates.map((candidate) => { const selected = selectedLifestyleScene?.id === candidate.id; return <button type="button" key={candidate.id} onClick={() => onSelectLifestyleScene(candidate)} className={`flex items-center justify-between gap-2 rounded-lg border p-2 text-left transition ${selected ? "border-[#43a16d] bg-[#ebf9f0] shadow-sm" : "border-[#d4e8dc] bg-white hover:border-[#7fbd98] hover:bg-[#f6fcf8]"}`}><span className="flex min-w-0 items-center gap-1.5"><span className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-white text-[#398160]"><Sparkles size={12} /></span><strong className="truncate text-[10px] text-[#285642]">{candidate.title}</strong></span>{selected && <CheckCircle2 size={13} className="shrink-0 text-[#20814f]" />}</button>; })}</div>
                  <details className="mt-2 rounded-lg border border-[#d8e8de] bg-[#f8fcf9] p-2"><summary className="flex cursor-pointer list-none items-center gap-1.5 text-[10px] font-bold text-[#39705a]"><AlertTriangle size={12} />避開不適合場景<span className="ml-auto font-medium text-[#718a7b]">選填</span></summary><div className="mt-2 flex flex-wrap gap-1.5">{(["home", "office", "outdoor"] as const).map((style) => { const avoided = lifestyleAvoidStyles.includes(style); const isCurrent = lifestyleStyle === style; return <button key={style} type="button" onClick={() => onToggleLifestyleAvoidStyle(style)} disabled={isCurrent} aria-pressed={avoided} className={`h-7 rounded-md border px-2 text-[10px] font-bold transition ${avoided ? "border-[#c78b36] bg-[#fff3dd] text-[#85520f]" : "border-[#cfe1d5] bg-white text-[#4e715e] hover:bg-[#eef8f1]"} disabled:cursor-not-allowed disabled:opacity-45`}>{avoided ? "避免 · " : ""}{MARKETPLACE_LIFESTYLE_STYLES[style].label}</button>; })}</div>{lifestyleRecommendation.avoidStyles.length > 0 && <p className="mt-2 text-[9px] leading-3 text-[#765426]">AI 建議避開：{lifestyleRecommendation.avoidStyles.map((style) => MARKETPLACE_LIFESTYLE_STYLES[style].label).join("、")}</p>}</details>
                </div>}
              </div>
            </div>
          </div>}</div>

          <details className="rounded-xl border border-[#d6e5f4] bg-white p-3"><summary className="flex cursor-pointer list-none items-center gap-2 text-xs font-bold text-[#315c8b]"><Palette size={14} />品牌樣式<span className="ml-auto text-[10px] font-medium text-[#74849a]">選填</span></summary><div className="mt-3"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-lg bg-[#e8f3ff] text-[#1f70d3]"><Palette size={15} /></span><div><span className="text-[11px] font-bold tracking-[0.1em] text-[#3974bf]">品牌視覺（選填）</span><p className="text-[10px] text-[#718197]">只會用於已選的輔助、賣點及情境圖，主圖保持平台合規。</p></div></div><div className="mt-3 grid gap-3 sm:grid-cols-2"><div><label htmlFor="brand-colour" className="text-[10px] font-bold text-[#526b87]">品牌重點色</label><div className="mt-1.5 flex items-center gap-2"><input id="brand-colour" type="color" value={brandStyle.accentColor} onChange={(event) => onBrandStyleChange({ ...brandStyle, accentColor: event.target.value.toUpperCase() })} className="h-9 w-10 cursor-pointer rounded-lg border border-[#cdddec] bg-white p-1" /><span className="rounded-lg border border-[#d8e4f1] px-2 py-2 text-xs font-bold text-[#48617e]">{brandStyle.accentColor}</span><div className="flex gap-1">{["#176BD2", "#2F7A63", "#A16324"].map((colour) => <button type="button" key={colour} onClick={() => onBrandStyleChange({ ...brandStyle, accentColor: colour })} aria-label={`選擇 ${colour}`} className={`h-6 w-6 rounded-full border-2 ${brandStyle.accentColor === colour ? "border-[#142f4d]" : "border-white"}`} style={{ backgroundColor: colour }} />)}</div></div></div><div><label htmlFor="brand-font" className="text-[10px] font-bold text-[#526b87]">賣點文字風格</label><select id="brand-font" value={brandStyle.fontStyle} onChange={(event) => onBrandStyleChange({ ...brandStyle, fontStyle: event.target.value as MarketplaceBrandStyle["fontStyle"] })} className="mt-1.5 h-9 w-full rounded-lg border border-[#d8e4f1] bg-[#fbfdff] px-2 text-xs font-bold text-[#48617e] outline-none focus:border-[#6ba1e2]">{Object.entries(MARKETPLACE_FONT_STYLES).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></div></div></div></details>
          <div className="rounded-xl border border-[#edd3a9] bg-[#fffaf1] px-3 py-2 text-[10px] leading-4 text-[#765426]"><AlertTriangle className="mr-1 inline text-[#bc7b11]" size={13} />請確認產品與實物相符；主圖會保持白底無字。</div>{isGenerating && <div aria-live="polite" className="rounded-xl border border-[#bcd8f4] bg-[#f2f8ff] p-3"><div className="flex items-center justify-between gap-3 text-xs font-bold text-[#245a9d]"><span className="flex items-center gap-1.5"><Loader2 className="animate-spin" size={14} />{generationProgress ? `正在處理：${generationProgress.roleTitle}（估算 ${generationProgress.completed + 1}/${generationProgress.total}）` : "正在準備商品圖片"}</span><span>{generationProgress ? `${generationProgress.percent}%` : "…"}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[#dceafa]"><div className="h-full rounded-full bg-[#2076d8] transition-[width] duration-700" style={{ width: `${generationProgress?.percent ?? 8}%` }} /></div><p className="mt-1.5 text-[10px] text-[#617c9c]">{generationProgress ? generationProgress.isOverEstimate ? `已等待 ${formatMarketplaceGenerationSeconds(generationProgress.elapsedSeconds)}。影像服務仍在完成最後處理，進度不會倒退；請保持此頁開啟。` : `已等待 ${formatMarketplaceGenerationSeconds(generationProgress.elapsedSeconds)} · 估計尚需 ${formatMarketplaceGenerationSeconds(generationProgress.estimatedRemainingSeconds)}。這是時間估算，完成後會自動顯示四張結果。` : "AI 正在排隊處理，請保持此頁開啟。"}</p></div>}<Button onClick={onGenerate} disabled={!referenceImages.length || !hasConfirmedCore || !selectedRoles.length || isDrafting || isGenerating} className="h-11 w-full rounded-xl bg-[#176bd2] text-sm font-bold text-white hover:bg-[#1059b8] disabled:opacity-60">{isGenerating ? <><Loader2 className="animate-spin" size={17} />正在建立 {generationProgress?.roleTitle ?? "商品"}…</> : <><Sparkles size={17} />建立 {creditCost} 張圖片</>}</Button>
        </section>
      </div>

      {result && <section ref={resultSectionRef} className="mt-2 scroll-mt-4 rounded-2xl border border-[#c9ddec] bg-white p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-sm font-bold text-[#203852]">已完成 {result.outputs.length}/{creditCost} 張圖片</h3><p className="mt-1 text-xs text-[#697b91]">可逐張下載，或先檢查全部結果後批量下載。</p></div><div className="flex flex-wrap gap-2"><Button onClick={onShareAll} disabled={result.outputs.length < 2 || isGenerating || sharingRole !== null} className="h-9 rounded-xl bg-[#25b96f] px-3 text-xs font-bold text-white hover:bg-[#1ba25e] disabled:opacity-60">{sharingRole === "all" ? <><Loader2 className="animate-spin" size={14} />準備相片…</> : <><MessageCircle size={14} />WhatsApp 分享全部</>}</Button><Button onClick={onDownloadAll} disabled={sharingRole !== null} variant="outline" className="h-9 rounded-xl border-[#bcd5ee] bg-white text-xs font-bold text-[#176bd2] hover:bg-[#edf5ff]"><Download size={14} />下載全部</Button><Button onClick={onOpenLibrary} variant="outline" className="h-9 rounded-xl border-[#c9dfd3] bg-white text-xs font-bold text-[#197250] hover:bg-[#f1fbf6]"><FolderOpen size={14} />我的相片</Button></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{result.outputs.map((output) => <article key={output.role} className="overflow-hidden rounded-xl border border-[#dbe6f0] bg-[#fbfdff]"><div className="aspect-square bg-[#f4f7fa]"><img src={output.url} alt={output.title} className="h-full w-full object-contain" /></div><div className="p-3"><strong className="block text-xs text-[#29425f]">{output.title}</strong><p className="mt-1 min-h-8 text-[10px] leading-4 text-[#718197]">{output.description}</p>{output.compositionCorrected && <p className="mt-2 flex items-center gap-1 text-[10px] font-bold text-[#197250]"><Sparkles size={12} />已按指定構圖重新生成</p>}{output.compositionWarning && <div className="mt-2 rounded-lg border border-[#efd4a6] bg-[#fffaf1] p-2 text-[10px] leading-4 text-[#805926]"><AlertTriangle className="mr-1 inline text-[#bd7a0f]" size={12} />{output.compositionWarning}<Button type="button" onClick={() => onRetryRole(output.role)} disabled={isGenerating} variant="ghost" className="mt-1 h-6 w-full rounded-md px-1 text-[10px] font-bold text-[#9a5a08] hover:bg-[#fff1d8]">{isGenerating && retryingRole === output.role ? <><Loader2 className="animate-spin" size={11} />重新建立中</> : <><RotateCcw size={11} />改善構圖，再建立一次</>}</Button></div>}<div className="mt-2 border-t border-[#e1eaf3] pt-2"><label className="block text-[10px] font-bold text-[#526b87]">不滿意這張？告訴 AI 怎樣重設計<textarea value={redesignInstructions[output.role] ?? ""} maxLength={500} disabled={isGenerating || typeof output.savedImageId !== "number"} onChange={(event) => setRedesignInstructions((current) => ({ ...current, [output.role]: event.target.value }))} placeholder="例如：改成較溫暖的家居窗邊構圖；保留產品不變" className="mt-1 min-h-16 w-full resize-y rounded-lg border border-[#d3e0ee] bg-white p-2 text-[10px] leading-4 text-[#425b76] outline-none focus:border-[#6ba1e2] disabled:bg-[#f4f7fa]" /></label><Button type="button" variant="outline" disabled={!redesignInstructions[output.role]?.trim() || isGenerating || typeof output.savedImageId !== "number"} onClick={() => { const instruction = redesignInstructions[output.role]?.trim(); if (instruction) { onRedesignRole(output.role, instruction); setRedesignInstructions((current) => ({ ...current, [output.role]: "" })); } }} className="mt-1.5 h-7 w-full rounded-lg border-[#b8d0ec] bg-white px-2 text-[10px] font-bold text-[#176bd2] hover:bg-[#edf5ff]">{isGenerating && retryingRole === output.role ? <><Loader2 className="animate-spin" size={11} />重新設計中</> : <><Sparkles size={11} />按要求重新設計這張（1 圖額度）</>}</Button>{typeof output.savedImageId !== "number" && <p className="mt-1 text-[9px] leading-3 text-[#8b6371]">此成品未能儲存到帳戶，請重新建立整個套組後才可逐張重設計。</p>}</div>{output.role === "detail" && (output.specificationLines ?? detailSpecificationLines).length > 0 && <SpecificationProofreadReminder outputKey={output.url} lines={output.specificationLines ?? detailSpecificationLines} acknowledged={specificationProofreadOutputs.has(output.url)} onAcknowledgedChange={(outputKey, next) => setSpecificationProofreadOutputs((current) => { const updated = new Set(current); if (next) updated.add(outputKey); else updated.delete(outputKey); return updated; })} />}{output.googleMerchantMetadataEmbedded && <p className="mt-2 flex items-center gap-1 text-[10px] font-bold text-[#197250]"><ShieldCheck size={12} />已嵌入 Google AI 標記</p>}<div className="mt-2 grid grid-cols-2 gap-1.5"><Button onClick={() => onShare(output.url, output.role)} disabled={isGenerating || sharingRole !== null} className="h-8 rounded-lg bg-[#25b96f] px-1 text-[10px] font-bold text-white hover:bg-[#1ba25e]">{sharingRole === output.role ? <><Loader2 className="animate-spin" size={12} />準備中</> : <><MessageCircle size={12} />WhatsApp</>}</Button><Button onClick={() => onDownload(output.url, output.role)} variant="ghost" className="h-8 rounded-lg px-1 text-[10px] font-bold text-[#176bd2] hover:bg-[#eaf3ff]"><Download size={12} />下載</Button></div><p className="mt-1.5 text-center text-[9px] leading-3 text-[#74839a]">開啟分享選單後選擇 WhatsApp</p></div></article>)}</div>{result.failures.length > 0 && <div className="mt-3 rounded-xl border border-[#edc9bd] bg-[#fff8f5] p-3 text-xs text-[#914833]"><strong>以下圖片暫時未完成：</strong><p className="mt-1 text-[11px] leading-5">已完成的成品會保留。可只重試失敗的一張，不會重複儲存主參考相片。</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{result.failures.map((failure) => <div key={failure.role} className="rounded-lg border border-[#efd5cb] bg-white/80 p-2"><strong className="block text-[11px]">{failure.title}</strong><p className="mt-0.5 min-h-8 text-[10px] leading-4 text-[#8c5745]">{failure.message}</p><Button type="button" onClick={() => onRetryRole(failure.role)} disabled={isGenerating} variant="outline" className="mt-2 h-7 w-full rounded-lg border-[#dfb9aa] bg-white px-2 text-[10px] font-bold text-[#9a4a32] hover:bg-[#fff0e9]">{isGenerating && retryingRole === failure.role ? <><Loader2 className="animate-spin" size={12} />重新建立中</> : <><RotateCcw size={12} />只重試這張</>}</Button></div>)}</div></div>}<div className="mt-3 rounded-xl border border-[#d7e6f5] bg-[#f4f9ff] p-3 text-[11px] leading-5 text-[#49627f]"><ShieldCheck className="mr-1.5 inline text-[#1a6ed2]" size={14} />{result.channel === "google" ? <>Google 套組成品已嵌入 `IPTC DigitalSourceType=trainedAlgorithmicMedia`。請直接使用下載原檔上傳，避免截圖、社交平台轉傳或其他重新儲存流程移除中繼資料；仍須核對實際 SKU、類目及 Merchant Center 診斷。</> : <>請把每張成品與實物及上架平台規則作最後核對。</>}</div></section>}
    </DialogContent>
  </Dialog>;
}
